select t.hm_id,t.hm_id hmId,t.attr_id,t.attr_id attrId,t.spec_cd,t.spec_cd specCd,t.status_cd,t.status_cd
statusCd,t.value,hm.hm_name hmName,hm.protocol_impl protocolImpl,hm.hm_type hmType,t.create_time createTime
from hardware_manufacturer_attr t
left join hardware_manufacturer hm on t.hm_id = hm.hm_id and hm.status_cd = '0'
where 1 =1

    and t.hm_id= #{hmId}


    and t.attr_id= #{attrId}


    and t.spec_cd= #{specCd}


    and t.status_cd= #{statusCd}


    and t.value= #{value}

order by t.create_time desc

    limit #{page}, #{row}

